import {
  createUserWithEmailAndPassword,
  onAuthStateChanged,
  signInWithEmailAndPassword,
  signOut,
  updateProfile
} from "firebase/auth";
import { doc, setDoc } from "firebase/firestore";
import { auth, db, firebaseEnabled } from "./app";

const DEMO_USER_KEY = "auraar_demo_user";

function readDemoUser() {
  const raw = localStorage.getItem(DEMO_USER_KEY);
  return raw ? JSON.parse(raw) : null;
}

function writeDemoUser(user) {
  if (user) {
    localStorage.setItem(DEMO_USER_KEY, JSON.stringify(user));
  } else {
    localStorage.removeItem(DEMO_USER_KEY);
  }
}

function createDemoUser(email, profile = {}) {
  return {
    uid: "demo-" + Date.now(),
    email,
    displayName: profile.fullName || email.split("@")[0],
    authMode: "demo",
    phoneNumber: profile.phoneNumber || null,
    address: profile.address || null
  };
}

export function subscribeToAuth(callback) {
  if (firebaseEnabled && auth) {
    return onAuthStateChanged(auth, callback);
  }

  callback(readDemoUser());
  return () => {};
}

export async function loginUser(email, password) {
  if (firebaseEnabled && auth) {
    const result = await signInWithEmailAndPassword(auth, email, password);
    return result.user;
  }

  const demoUser = createDemoUser(email);
  writeDemoUser(demoUser);
  return demoUser;
}

export async function signupUser(email, password, profile = {}) {
  const { fullName, address, phoneNumber } = profile;

  if (firebaseEnabled && auth) {
    const result = await createUserWithEmailAndPassword(auth, email, password);
    const newUser = result.user;

    if (fullName) {
      await updateProfile(newUser, { displayName: fullName });
    }

    if (db) {
      await setDoc(doc(db, "users", newUser.uid), {
        fullName: fullName || null,
        email,
        address: address || null,
        phoneNumber: phoneNumber || null,
        createdAt: new Date().toISOString()
      });
    }

    return newUser;
  }

  const demoUser = createDemoUser(email, profile);
  writeDemoUser(demoUser);
  return demoUser;
}

export async function logoutUser() {
  if (firebaseEnabled && auth) {
    await signOut(auth);
    return;
  }

  writeDemoUser(null);
}
